def _replace(table, name, expression):
    op.drop_constraint(name, table, type_="check")
    op.create_check_constraint(name, table, expression)


def upgrade():
    op.add_column(
        "task_originals",
        sa.Column("storage_ref", JSONB(none_as_null=True), nullable=True),
    )
    op.create_check_constraint(
        "ck_task_original_storage_ref", "task_originals", TASK_CHECK
    )
    _replace(
        "task_originals",
        "ck_task_original_location",
        "storage_ref IS NOT NULL OR location_id='4fcc68cb-ce7a-5da2-ab39-143a6de6d0f7'::uuid",
    )
    _replace(
        "task_originals",
        "ck_task_original_key",
        "object_key=COALESCE(storage_ref->>'key_prefix','') || '__aap_task_originals__/' || task_id::text || '/' || id::text || '/payload'",
    )
    _replace("managed_original_creations", "ck_managed_creation_scope", NEW_SCOPE)
    for table, name, old, new in CHECKS:
        _replace(table, name, new)
    for table in (
        "task_originals",
        "comment_attachment_uploads",
        "guide_asset_uploads",
        "raster_mask_objects",
    ):
        op.execute(
            f"CREATE INDEX ix_{table}_saved_location ON {table} ((storage_ref->>'location_id'))"
        )
    op.execute(NEW_GUARD)


def downgrade():
    op.execute(
        "LOCK TABLE task_originals,managed_original_creations,comment_attachment_uploads,guide_asset_uploads,raster_mask_objects,storage_bindings IN ACCESS EXCLUSIVE MODE"
    )
    op.execute("""
        DO $$ BEGIN
            IF EXISTS(SELECT 1 FROM task_originals WHERE storage_ref IS NOT NULL)
              OR EXISTS(SELECT 1 FROM managed_original_creations WHERE owner_kind='task' AND configuration->>'schema'='2' AND configuration ? 'original_ref')
              OR EXISTS(SELECT 1 FROM comment_attachment_uploads WHERE storage_ref->>'schema'='2')
              OR EXISTS(SELECT 1 FROM guide_asset_uploads WHERE storage_ref->>'schema'='2')
              OR EXISTS(SELECT 1 FROM raster_mask_objects WHERE storage_ref->>'schema'='2')
              OR EXISTS(SELECT 1 FROM storage_bindings WHERE purpose='annotations' AND generation<>1) THEN
                RAISE EXCEPTION 'Saved annotation-file responsibility prevents destructive downgrade' USING ERRCODE='23514';
            END IF;
        END $$;
    """)
    op.execute(OLD_GUARD)
    for table, name, old, new in CHECKS:
        _replace(table, name, old)
    for table in (
        "task_originals",
        "comment_attachment_uploads",
        "guide_asset_uploads",
        "raster_mask_objects",
    ):
        op.drop_index("ix_" + table + "_saved_location", table_name=table)
    _replace("managed_original_creations", "ck_managed_creation_scope", OLD_SCOPE)
    _replace(
        "task_originals",
        "ck_task_original_key",
        "object_key='__aap_task_originals__/' || task_id::text || '/' || id::text || '/payload'",
    )
    _replace(
        "task_originals",
        "ck_task_original_location",
        "location_id='4fcc68cb-ce7a-5da2-ab39-143a6de6d0f7'::uuid",
    )
    op.drop_constraint("ck_task_original_storage_ref", "task_originals", type_="check")
    op.drop_column("task_originals", "storage_ref")
